public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0 || arr.length % 2 != 0) {
        return false;
    }
    int n = arr.length;
    int[] count = new int[k];
    for (int num : arr) {
        int rem = ((num % k) + k) % k;
        count[rem]++;
    }
    // Remainder 0 must be even
    if (count[0] % 2 != 0) {
        return false;
    }
    // If k is even, remainder k/2 must be even
    if (k % 2 == 0) {
        if (count[k / 2] % 2 != 0) {
            return false;
        }
    }
    // For other remainders
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) { // already handled when k even
            continue;
        }
        if (count[r] != count[k - r]) {
            return false;
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0 || edges == null || hasApple == null || hasApple.length != n) {
        return 0;
    }
    java.util.List<Integer>[] graph = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new java.util.ArrayList<>();
    }
    for (int[] e : edges) {
        if (e == null || e.length != 2) continue;
        int u = e[0], v = e[1];
        if (u < 0 || u >= n || v < 0 || v >= n) continue;
        graph[u].add(v);
        graph[v].add(u);
    }
    int[] parent = new int[n];
    for (int i = 0; i < n; i++) parent[i] = -1;
    int[] order = new int[n];
    int idx = 0;
    java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
    stack.push(0);
    while (!stack.isEmpty()) {
        int node = stack.pop();
        order[idx++] = node;
        for (int nei : graph[node]) {
            if (nei != parent[node]) {
                parent[nei] = node;
                stack.push(nei);
            }
        }
    }
    int[] time = new int[n];
    for (int i = n - 1; i >= 0; i--) {
        int node = order[i];
        for (int nei : graph[node]) {
            if (nei != parent[node]) {
                if (time[nei] > 0 || hasApple[nei]) {
                    time[node] += time[nei] + 2;
                }
            }
        }
    }
    return time[0];
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    int[] freq = new int[26];
    for (char c : s.toCharArray()) {
        if (c >= 'a' && c <= 'z') {
            freq[c - 'a']++;
        } else {
            // If characters outside 'a'-'z' are present, treat them separately
            // by using a map or ignoring them. Here we simply ignore them.
        }
    }
    StringBuilder result = new StringBuilder(s.length());
    int remaining = s.length();
    while (remaining > 0) {
        // Ascending pass: pick smallest available characters
        for (int i = 0; i < 26 && remaining > 0; i++) {
            if (freq[i] > 0) {
                result.append((char) (i + 'a'));
                freq[i]--;
                remaining--;
            }
        }
        // Descending pass: pick largest available characters
        for (int i = 25; i >= 0 && remaining > 0; i--) {
            if (freq[i] > 0) {
                result.append((char) (i + 'a'));
                freq[i]--;
                remaining--;
            }
        }
    }
    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length <= 1) {
        return false;
    }
    int n = nums.length;
    int totalSum = 0;
    for (int v : nums) {
        totalSum += v;
    }

    // sums[k] holds all possible sums of subsets of size k
    @SuppressWarnings("unchecked")
    Set<Integer>[] sums = new Set[n + 1];
    for (int i = 0; i <= n; i++) {
        sums[i] = new HashSet<>();
    }
    sums[0].add(0);

    for (int num : nums) {
        // iterate k from n-1 down to 1 to avoid using updated values in the same iteration
        for (int k = n - 1; k >= 1; k--) {
            for (int prevSum : sums[k - 1]) {
                sums[k].add(prevSum + num);
            }
        }
    }

    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) {
            continue; // target sum not integer
        }
        int target = (totalSum * k) / n;
        if (sums[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        return 0;
    }
    int prev2 = 0; // dp[0]
    int prev1 = 0; // dp[1]
    for (int i = 2; i <= n; i++) {
        int costFromPrev1 = prev1 + cost[i - 1];
        int costFromPrev2 = prev2 + cost[i - 2];
        int curr = Math.min(costFromPrev1, costFromPrev2);
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1;
}

public int uniqueMorseRepresentations(String[] words) {
    if (words == null || words.length == 0) {
        return 0;
    }
    String[] morse = {".-","-...","-.-.","-..",".","..-.","--.","....","..",
                      ".---","-.-",".-..","--","-.","---",".--.","--.-",".-.",
                      "...","-","..-","...-",".--","-..-","-.--","--.."};
    java.util.HashSet<String> set = new java.util.HashSet<>();
    for (String word : words) {
        if (word == null) {
            continue;
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < word.length(); i++) {
            char c = word.charAt(i);
            if (c >= 'a' && c <= 'z') {
                sb.append(morse[c - 'a']);
            } else if (c >= 'A' && c <= 'Z') {
                sb.append(morse[c - 'A']);
            }
        }
        set.add(sb.toString());
    }
    return set.size();
}

public boolean hasAllCodes(String s, int k) {
    if (k <= 0) {
        return true;
    }
    if (s == null || s.length() < k) {
        return false;
    }
    int total = 1 << k; // total number of possible binary strings of length k
    boolean[] seen = new boolean[total];
    int mask = total - 1;
    int code = 0;
    int count = 0;
    for (int i = 0; i < s.length(); i++) {
        code = ((code << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            if (!seen[code]) {
                seen[code] = true;
                count++;
                if (count == total) {
                    return true;
                }
            }
        }
    }
    return false;
}

