public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    long maxSum = nums[0];
    long minSum = nums[0];
    long currentMax = nums[0];
    long currentMin = nums[0];
    for (int i = 1; i < nums.length; i++) {
        int val = nums[i];
        currentMax = Math.max(val, currentMax + val);
        maxSum = Math.max(maxSum, currentMax);
        currentMin = Math.min(val, currentMin + val);
        minSum = Math.min(minSum, currentMin);
    }
    long result = Math.max(maxSum, -minSum);
    return (int) result;
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0;
    }
    // Generate Fibonacci numbers up to k
    java.util.List<Long> fibs = new java.util.ArrayList<>();
    fibs.add(1L);
    fibs.add(1L);
    while (true) {
        long next = fibs.get(fibs.size() - 1) + fibs.get(fibs.size() - 2);
        if (next > k) {
            break;
        }
        fibs.add(next);
    }
    int count = 0;
    int idx = fibs.size() - 1;
    long remaining = k;
    while (remaining > 0) {
        while (fibs.get(idx) > remaining) {
            idx--;
        }
        remaining -= fibs.get(idx);
        count++;
    }
    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.ArrayList<Integer> factors = new java.util.ArrayList<>();
    for (int i = 1; (long) i * i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
            int other = n / i;
            if (other != i) {
                factors.add(other);
            }
        }
    }
    java.util.Collections.sort(factors);
    if (k > factors.size()) {
        return -1;
    }
    return factors.get(k - 1);
}

public String makeGood(String s) {
