    }
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int len = stack.length();
        if (len > 0) {
            char last = stack.charAt(len - 1);
            if (Character.toLowerCase(c) == Character.toLowerCase(last)) {
                stack.deleteCharAt(len - 1);
                continue;
            }
        }
        stack.append(c);
    }
    return stack.toString();
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) return 0;
    int[] max = new int[1];
    dfs(0, new java.util.HashSet<>(), 0, s, max);
    return max[0];
}

private void dfs(int pos, java.util.Set<String> used, int count, String s, int[] max) {
    if (pos == s.length()) {
        if (count > max[0]) max[0] = count;
        return;
    }
    for (int i = pos; i < s.length(); i++) {
        String sub = s.substring(pos, i + 1);
        if (!used.contains(sub)) {
            used.add(sub);
            dfs(i + 1, used, count + 1, s, max);
            used.remove(sub);
        }
    }
}

public int minOperations(String[] logs) {
    if (logs == null || logs.length == 0) {
        return 0;
    }
    int depth = 0;
    for (String log : logs) {
        if (log == null) {
            continue;
        }
        if (log.equals("./")) {
            // stay in current folder, no change
            continue;
        } else if (log.equals("../")) {
            if (depth > 0) {
                depth--;
            }
        } else {
            // any other string ending with '/' is considered a folder entry
            if (log.endsWith("/")) {
                depth++;
            }
        }
    }
    return depth;
}

public String getSmallestString(int n, int k) {
    if (n <= 0) {
        return "";
    }
    // Minimum possible sum is n (all 'a'), maximum is 26*n (all 'z')
    if (k < n || k > 26 * n) {
        return "";
    }
    char[] result = new char[n];
    java.util.Arrays.fill(result, 'a');
    int delta = k - n; // additional value needed beyond all 'a's
    for (int i = n - 1; i >= 0 && delta > 0; i--) {
        int add = Math.min(25, delta); // each position can increase by at most 25
        result[i] = (char) ('a' + add);
        delta -= add;
    }
    return new String(result);
}

